using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Collections.Generic;
sealed partial class Companion {
 internal void WidgetAppearance(){using(var f=Dialog("Floating capture button",450,510)){var col=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false};col.Controls.Add(new Label{Text="Only this button · notes keep their own appearance",AutoSize=true});var slider=new ThemeSlider{Minimum=30,Maximum=100,Value=store.Pref.WidgetOpacity,Width=350};var label=new Label{Text="Button opacity · "+slider.Value+"%",AutoSize=true};slider.ValueChanged+=(s,e)=>{store.Pref.WidgetOpacity=slider.Value;label.Text="Button opacity · "+slider.Value+"%";if(captureButton!=null)captureButton.Opacity=slider.Value/100.0;store.SavePrefs();};col.Controls.Add(label);col.Controls.Add(slider);var locked=new CheckBox{Text="Lock this button in place",Checked=store.Pref.WidgetLocked,AutoSize=true};locked.CheckedChanged+=(s,e)=>{store.Pref.WidgetLocked=locked.Checked;store.SavePrefs();};col.Controls.Add(locked);var top=new CheckBox{Text="Keep above other applications",Checked=store.Pref.WidgetTop,AutoSize=true};top.CheckedChanged+=(s,e)=>{store.Pref.WidgetTop=top.Checked;if(captureButton!=null)captureButton.TopMost=top.Checked;store.SavePrefs();};col.Controls.Add(top);var snap=new CheckBox{Text="Snap near screen edges after dragging",Checked=store.Pref.WidgetSnap,AutoSize=true};snap.CheckedChanged+=(s,e)=>{store.Pref.WidgetSnap=snap.Checked;store.SavePrefs();};col.Controls.Add(snap);var import=new Button{Text="Choose my button image…",AutoSize=true};import.Click+=(s,e)=>ImportWidgetImage();col.Controls.Add(import);var reset=new Button{Text="Restore camera icon",AutoSize=true};reset.Click+=(s,e)=>{if(File.Exists(WidgetImagePath))File.Delete(WidgetImagePath);LoadWidgetImage();};col.Controls.Add(reset);col.Controls.Add(new Label{Text="Drag to move · click to capture · right-click for more.\nPosition is remembered. The button stays off until enabled.",AutoSize=true,MaximumSize=new Size(380,0)});f.Controls.Add(col);ThemeControls(f);f.ShowDialog(this);}}
 internal void SetupEditing4(){BorderlessWindow.Attach(this,()=>store.Pref.Locked||IsTabbed);ThemeTasks.TransparencyPaint=SolidText.PaintTasks;SetupWindowSymbols();DoubleBuffered=true;SetStyle(ControlStyles.ResizeRedraw,true);notes.SelectionMode=SelectionMode.MultiExtended;editor.FormatMenu=menu=>AddFormatting(menu,editor);foreach(var m in memos)m.text.FormatMenu=menu=>AddFormatting(menu,m.text);Add(format,"Heading…",()=>FormatHeading(1));}
 internal void FormatHeading(int level){if(formattedPage.Visible){int line=formattedPage.SourceLineAt(formattedPage.SelectionStart);int at=0;for(int i=0;i<line;i++){int next=editor.Text.IndexOf('\n',at);if(next<0)break;at=next+1;}editor.Select(at,0);}Heading(editor,level);if(typingMode=="Plain text"){SaveNow();UpdatePageView();}}
 internal void AddFormatting(ContextMenuStrip menu,RichTextBox field){menu.Items.Add(new ToolStripSeparator());var headings=new ToolStripMenuItem("Make heading");foreach(int n in new[]{1,2,3}){int level=n;headings.DropDownItems.Add("Heading "+n,null,(s,e)=>Heading(field,level));}menu.Items.Add(headings);menu.Items.Add("Make bold",null,(s,e)=>{if(field.SelectionLength>0)field.SelectedText="**"+field.SelectedText+"**";});menu.Items.Add("Make task",null,(s,e)=>PrefixLines(field,"- [ ] "));}
 internal void Heading(RichTextBox field,int level){int first=field.SelectionStart==0?0:field.Text.LastIndexOf('\n',field.SelectionStart-1)+1,last=field.SelectionStart+field.SelectionLength;int end=field.Text.IndexOf('\n',last);if(end<0)end=field.TextLength;field.Select(first,end-first);field.SelectedText=String.Join("\n",field.SelectedText.Split('\n').Select(x=>new string('#',level)+" "+System.Text.RegularExpressions.Regex.Replace(x,@"^#{1,6}\s+","")));}
 internal void PrefixLines(RichTextBox field,string prefix){int first=field.SelectionStart==0?0:field.Text.LastIndexOf('\n',field.SelectionStart-1)+1;field.Select(first,field.SelectionStart+field.SelectionLength-first);field.SelectedText=prefix+field.SelectedText.Replace("\n","\n"+prefix);}
 internal void DeleteSelectedPages(){var pages=notes.SelectedItems.Cast<Note>().ToArray();if(pages.Length<2){DeletePage(current,true);return;}if(!ConfirmDelete(pages.Length+" selected pages"))return;string group=Guid.NewGuid().ToString();foreach(var n in pages){int count=deletedPages.Count;DeletePage(n,false);if(deletedPages.Count>count)deletedPages.Peek().Group=group;}}
 internal static Color ColourFromHSV(double h,double s,double v){double c=v*s,x=c*(1-Math.Abs((h/60)%2-1)),m=v-c;double a=0,b=0,d=0;if(h<60){a=c;b=x;}else if(h<120){a=x;b=c;}else if(h<180){b=c;d=x;}else if(h<240){b=x;d=c;}else if(h<300){a=x;d=c;}else{a=c;d=x;}return Color.FromArgb((int)((a+m)*255),(int)((b+m)*255),(int)((d+m)*255));}
 internal Color? PickColour(Form parent,Color initial){using(var f=Dialog("Choose colour",470,660)){Color chosen=initial;var col=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false};var preview=new Panel{BackColor=chosen,Width=390,Height=45};var hex=new TextBox{Text=ColorTranslator.ToHtml(chosen),Width=390};var hint=new Label{Text="Pick a swatch or type a hex colour",AutoSize=true};var grid=new FlowLayoutPanel{Width=400,Height=200};string[] values={"#ecede9","#202329","#486d6e","#91d9f4","#ddb4db","#b7d5a0","#d6c89e","#ffba49","#cd532f","#df4758","#ef93a3","#883c72","#6554af","#374fa4","#0a91a0","#12675d","#37824d","#6eb34f","#af7636","#653d27","#f8f6f0","#b6bdc5","#69716b","#27363a"};foreach(string value in values){string picked=value;var b=new Button{BackColor=ColorTranslator.FromHtml(value),Width=45,Height=40,FlatStyle=FlatStyle.Flat,Text="",AccessibleName=value};b.Click+=(s,e)=>hex.Text=picked;grid.Controls.Add(b);}var shade=new Panel{Width=390,Height=125};var hue=new ThemeSlider{Minimum=0,Maximum=359,Value=(int)initial.GetHue(),Width=390,TickStyle=TickStyle.None};shade.Paint+=(s,e)=>{for(int y=0;y<shade.Height;y+=4)for(int x=0;x<shade.Width;x+=4)using(var b=new SolidBrush(ColourFromHSV(hue.Value,x/(double)shade.Width,1-y/(double)shade.Height)))e.Graphics.FillRectangle(b,x,y,4,4);};Action<Point> chooseShade=point=>hex.Text=ColorTranslator.ToHtml(ColourFromHSV(hue.Value,Math.Max(0,Math.Min(1,point.X/(double)shade.Width)),Math.Max(0,Math.Min(1,1-point.Y/(double)shade.Height))));shade.MouseDown+=(s,e)=>chooseShade(e.Location);shade.MouseMove+=(s,e)=>{if(e.Button==MouseButtons.Left)chooseShade(e.Location);};hue.ValueChanged+=(s,e)=>shade.Invalidate();col.Controls.Add(new Label{Text="Drag to choose a shade · slide to change its hue",AutoSize=true});col.Controls.Add(shade);col.Controls.Add(hue);var use=new Button{Text="Use colour",Width=390,Height=38,DialogResult=DialogResult.OK};hex.TextChanged+=(s,e)=>{try{string v=hex.Text.Trim();if(!System.Text.RegularExpressions.Regex.IsMatch(v,@"^#[0-9a-fA-F]{6}$"))throw new Exception();chosen=ColorTranslator.FromHtml(v);preview.BackColor=chosen;use.Enabled=true;hint.Text=v.ToUpperInvariant();}catch{use.Enabled=false;hint.Text="Use # followed by six hex digits";}};col.Controls.Add(hint);col.Controls.Add(hex);col.Controls.Add(preview);col.Controls.Add(grid);col.Controls.Add(use);f.Controls.Add(col);ThemeControls(f);preview.BackColor=chosen;foreach(Button b in grid.Controls)b.BackColor=ColorTranslator.FromHtml(b.AccessibleName);return f.ShowDialog(parent)==DialogResult.OK?(Color?)chosen:null;}}
}
